<?php
if (!defined('ABSPATH')) exit;
add_action('rest_api_init',function(){ register_rest_route('hirehub/v1','/jobs',array('methods'=>WP_REST_Server::READABLE,'callback'=>'hirehub_rest_jobs','permission_callback'=>'__return_true','args'=>array('search'=>array('sanitize_callback'=>'sanitize_text_field'),'location'=>array('sanitize_callback'=>'sanitize_text_field'),'paged'=>array('default'=>1,'sanitize_callback'=>'absint'),'per_page'=>array('default'=>10,'sanitize_callback'=>'absint')))); });
function hirehub_rest_jobs(WP_REST_Request $request){ $args=array('post_type'=>'hirehub_job','post_status'=>'publish','posts_per_page'=>min(50,max(1,(int)$request['per_page'])),'paged'=>max(1,(int)$request['paged']),'s'=>$request['search']); if($request['location']) $args['meta_query']=array(array('key'=>'_location','value'=>$request['location'],'compare'=>'LIKE')); $q=new WP_Query($args); $items=array(); foreach($q->posts as $post){ $id=$post->ID; $items[]=array('id'=>$id,'title'=>get_the_title($id),'url'=>get_permalink($id),'company'=>get_post_meta($id,'_company',true),'location'=>get_post_meta($id,'_location',true),'salary'=>get_post_meta($id,'_salary',true),'experience'=>get_post_meta($id,'_experience',true)); } return new WP_REST_Response($items,200); }
